-- ============================================
-- 피복 구매관리 시스템 - 종합 확장 시드 데이터
-- 실행 전제: 001~006 마이그레이션 + seed.sql + seed_additional.sql 완료
-- ============================================
-- 추가 데이터:
--   판매소 2개 추가 (총 5개)
--   판매소 담당자 2명
--   배송지 4개 추가 (총 10개)
--   카테고리 9개 추가
--   품목 30개 추가 (총 50개: 완제품 34, 맞춤 16)
--   규격 62개 추가 (총 104개)
--   재고 기초: 각 판매소 50여 항목 (약 210개 추가)
--   입고 이력 50건
--   재고 조정 40건
--   오프라인 구매 20건
--   온라인 구매 20건
--   맞춤피복 구매 20건 + 체척권 20건
-- ============================================


-- ============================================
-- 섹션 1: 판매소 2개 추가
-- ============================================
INSERT INTO stores (id, name, address, phone, manager_name)
SELECT * FROM (VALUES
  ('a1000000-0000-0000-0000-000000000004'::uuid, '제4피복판매소', '부산시 해운대구 센텀시티로 50', '051-111-2222', '윤판매'),
  ('a1000000-0000-0000-0000-000000000005'::uuid, '제5피복판매소', '광주시 서구 상무대로 100',   '062-333-4444', '조판매')
) AS v(id, name, address, phone, manager_name)
WHERE NOT EXISTS (SELECT 1 FROM stores WHERE id = v.id);


-- ============================================
-- 섹션 2: 판매소 담당자 계정 2명 추가
-- ============================================
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM auth.users WHERE id = 'c2000000-0000-0000-0000-000000000004') THEN
    INSERT INTO auth.users (id, instance_id, email, encrypted_password, email_confirmed_at, role, aud, created_at, updated_at)
    VALUES
      ('c2000000-0000-0000-0000-000000000004', '00000000-0000-0000-0000-000000000000', 'store4@test.com', crypt('test1234', gen_salt('bf')), now(), 'authenticated', 'authenticated', now(), now()),
      ('c2000000-0000-0000-0000-000000000005', '00000000-0000-0000-0000-000000000000', 'store5@test.com', crypt('test1234', gen_salt('bf')), now(), 'authenticated', 'authenticated', now(), now());

    INSERT INTO auth.identities (id, user_id, identity_data, provider, provider_id, last_sign_in_at, created_at, updated_at)
    VALUES
      ('c2000000-0000-0000-0000-000000000004', 'c2000000-0000-0000-0000-000000000004', jsonb_build_object('sub', 'c2000000-0000-0000-0000-000000000004', 'email', 'store4@test.com'), 'email', 'c2000000-0000-0000-0000-000000000004', now(), now(), now()),
      ('c2000000-0000-0000-0000-000000000005', 'c2000000-0000-0000-0000-000000000005', jsonb_build_object('sub', 'c2000000-0000-0000-0000-000000000005', 'email', 'store5@test.com'), 'email', 'c2000000-0000-0000-0000-000000000005', now(), now(), now());

    INSERT INTO users (id, email, name, role, store_id)
    VALUES
      ('c2000000-0000-0000-0000-000000000004', 'store4@test.com', '윤판매', 'store', 'a1000000-0000-0000-0000-000000000004'),
      ('c2000000-0000-0000-0000-000000000005', 'store5@test.com', '조판매', 'store', 'a1000000-0000-0000-0000-000000000005');

    RAISE NOTICE '판매소 담당자 2명 생성 완료';
  ELSE
    RAISE NOTICE '판매소 담당자가 이미 존재합니다. 건너뜁니다.';
  END IF;
END $$;


