-- ============================================
-- 완료 확인
-- ============================================
SELECT
  (SELECT COUNT(*) FROM stores)              AS stores,
  (SELECT COUNT(*) FROM tailors)             AS tailors,
  (SELECT COUNT(*) FROM users WHERE role='user') AS users,
  (SELECT COUNT(*) FROM delivery_zones)      AS delivery_zones,
  (SELECT COUNT(*) FROM categories)         AS categories,
  (SELECT COUNT(*) FROM products)           AS products,
  (SELECT COUNT(*) FROM product_specs)      AS product_specs,
  (SELECT COUNT(*) FROM inventory)          AS inventory_items,
  (SELECT COUNT(*) FROM inventory_log)      AS inventory_logs,
  (SELECT COUNT(*) FROM orders)             AS orders,
  (SELECT COUNT(*) FROM order_items)        AS order_items,
  (SELECT COUNT(*) FROM tailoring_tickets)  AS tickets;
